    raise SystemExit("analysis.json 格式不严格符合要求")
analysis = json.loads(raw)
if set(analysis) != {"total", "max"}:
    raise SystemExit("analysis.json 键不符合要求")
if any(type(analysis[key]) is not int for key in ("total", "max")):
    raise SystemExit("analysis.json 数值类型不是整数")
def collect_integers(value, values):
    if isinstance(value, bool):
        return
    if isinstance(value, int):
        values.append(value)
        return
    if isinstance(value, list):
        for item in value:
            collect_integers(item, values)
        return
    if isinstance(value, dict):
        for item in value.values():
            collect_integers(item, values)
with input_path.open("r", encoding="utf-8") as handle:
    data = json.load(handle)
values = []
collect_integers(data, values)
recomputed = {"total": sum(values), "max": max(values)}
if analysis != recomputed:
    raise SystemExit(f"回读结果与重算不一致: analysis={analysis}, recomputed={recomputed}")
print(raw)'"' "

